files.styles.css:
body { font-family: system-ui; max-width: 600px; margin: 24px auto; line-height: 1.6; }
code { background: #f1f5f9; padding: 1px 4px; border-radius: 4px; }
pre { background: #0f172a; color: #e2e8f0; padding: 12px; border-radius: 8px; overflow:auto; }
pre code { background: none; color: inherit; }
blockquote { border-left: 3px solid #cbd5e1; margin: 12px 0; padding-left: 12px; color: #475569; }
abbr { cursor: help; text-decoration: underline dotted; }
